package com.vms.vendorcontractmanagement.exception; import org.springframework.web.bind.annotation.*; import org.springframework.http.*; import org.springframework.web.bind.*; import java.time.*; import java.util.*;
@RestControllerAdvice public class GlobalExceptionHandler { record ErrorResponse(Instant timestamp,int status,String error,String message){ } @ExceptionHandler(ApiException.class) ResponseEntity<ErrorResponse> api(ApiException e){return ResponseEntity.status(e.status).body(new ErrorResponse(Instant.now(),e.status.value(),e.status.getReasonPhrase(),e.getMessage()));} @ExceptionHandler(MethodArgumentNotValidException.class) ResponseEntity<ErrorResponse> validation(MethodArgumentNotValidException e){String m=e.getBindingResult().getFieldErrors().stream().findFirst().map(x->x.getField()+": "+x.getDefaultMessage()).orElse("Validation failed");return ResponseEntity.badRequest().body(new ErrorResponse(Instant.now(),400,"Bad Request",m));} @ExceptionHandler(Exception.class) ResponseEntity<ErrorResponse> generic(Exception e){return ResponseEntity.status(500).body(new ErrorResponse(Instant.now(),500,"Internal Server Error","An unexpected error occurred"));} }
